   278  void IptcData::printStructure(std::ostream& out, const Slice<byte*>& bytes, size_t depth) {
   279    if (bytes.size() < 3) {
   280      return;
   281    }
   282    size_t i = 0;
   283    while (i < bytes.size() - 3 && bytes.at(i) != 0x1c)
   284      i++;
   285    out << Internal::indent(++depth) << "Record | DataSet | Name                     | Length | Data" << std::endl;
   286    while (i < bytes.size() - 3) {
   287      if (bytes.at(i) != 0x1c) {
   288        break;
   289      }
   290      char buff[100];
   291      uint16_t record = bytes.at(i + 1);
   292      uint16_t dataset = bytes.at(i + 2);
   293      Internal::enforce(bytes.size() - i >= 5, ErrorCode::kerCorruptedMetadata);
   294      uint16_t len = getUShort(bytes.subSlice(i + 3, bytes.size()), bigEndian);
   295      snprintf(buff, sizeof(buff), "  %6hu | %7hu | %-24s | %6hu | ", record, dataset,
   296               Exiv2::IptcDataSets::dataSetName(dataset, record).c_str(), len);
   297
   298      Internal::enforce(bytes.size() - i >= 5 + static_cast<size_t>(len), ErrorCode::kerCorruptedMetadata);
   299      out << buff << Internal::binaryToString(makeSlice(bytes, i + 5, i + 5 + (len > 40 ? 40 : len)))
   300          << (len > 40 ? "..." : "") << std::endl;
   301      i += 5 + len;
   302    }
   303  }
